mapper.select:
SELECT EXISTS(
    SELECT 1
    FROM performance_public_notice
    WHERE performance_project_id = #{performanceProjectId}
      AND public_notice_id = #{publicNoticeId}
)

mapper.insert:
INSERT INTO performance_public_notice (
    performance_project_id, public_notice_id
) VALUES (
    #{performanceProjectId}, #{publicNoticeId}
)

mapper.delete:
DELETE FROM performance_public_notice
WHERE performance_project_id = #{performanceProjectId}
  AND public_notice_id = #{publicNoticeId}
